function expandIpRange(value, maxHosts = 1024) {
  const parts = String(value || "").split("-").map((part) => part.trim());
  if (parts.length !== 2 || !parts[0] || !parts[1]) return [];

  let end = parts[1];
  if (!end.includes(".")) {
    const startParts = parts[0].split(".");
    if (startParts.length === 4) {
      end = startParts.slice(0, 3).concat(end).join(".");
    }
  }

  const startInt = ipToInt(parts[0]);
  const endInt = ipToInt(end);
  if (startInt === null || endInt === null) return [];

  const start = Math.min(startInt, endInt);
  const finish = Math.max(startInt, endInt);
  const total = finish - start + 1;

  if (total > maxHosts) {
    throw new Error("Prepare Queue Error: IP range expands to " + total + " hosts. Limit is " + maxHosts + ".");
  }

  return Array.from({ length: total }, (_, index) => intToIp(start + index));
}

