  out.parameters.ssh_user = user;
  delete out.parameters.ssh_users;

  out.ssh_port = port;
  out.sshPort = port;
  out.parameters.ssh_port = port;

  const serverLabel = safeServerName(target, index);

  out.serverLabel = serverLabel;
  out.serverName = serverLabel;
  out.ip = target;

  // สำคัญ: ห้ามบังคับใช้ scanJobId เดียวกันทุก IP
  // ให้เก็บ scanJobId / signature ของ item นั้น ๆ
  out.scanJobId = originalItem.scanJobId || out.scanJobId || null;
  out.projectId = originalItem.projectId || out.projectId || null;
  out.callbackUrl = originalItem.callbackUrl || out.callbackUrl || null;
  out.signature = originalItem.signature || out.signature || null;

  return out;
}

// ถ้าไม่ใช่ Vuls ให้ปล่อยผ่านเหมือนเดิม เพื่อไม่กระทบ tool อื่น
const hasVuls = bodyItems.some(item => getToolName(item) === "vuls");

if (!hasVuls) {
  return [
    {
      json: input
    }
  ];
}

const normalizedBody = [];

// เก็บ users/ports แบบ global เผื่อ body ถูก split target มาแล้ว
let globalUsers = [];
let globalPorts = [];

for (const item of bodyItems) {
  if (getToolName(item) !== "vuls") continue;

  const users = getUsers(item);
  const ports = getPorts(item);

  if (users.length > globalUsers.length) {
    globalUsers = users;
  }

  if (ports.length > globalPorts.length) {
    globalPorts = ports;
  }
}

for (const itemIndex in bodyItems) {
  const item = bodyItems[itemIndex];

  if (getToolName(item) !== "vuls") {
    normalizedBody.push(item);
    continue;
  }

  const targets = getTargets(item);
  const users = getUsers(item);
  const ports = getPorts(item);

  if (!targets.length) {
    throw new Error("Vuls: missing target IP");
  }

  // กรณี body ถูก split มาแล้ว:
  // item 1 target เดียว แต่ ssh_user ยังเป็นหลายบรรทัดเหมือนกันทุก item
  if (bodyItems.length > 1 && targets.length === 1) {
    const target = targets[0];

    const user =
      globalUsers.length > 1
        ? globalUsers[Number(itemIndex)]
        : users[0] || globalUsers[0];

    const port =
      globalPorts.length > 1
        ? toPort(globalPorts[Number(itemIndex)])
        : toPort(ports[0] || globalPorts[0] || 22);

    if (!user) {
      throw new Error(
        `Vuls: target ${target} has no matching ssh_user at item index ${itemIndex}`
      );
    }

    normalizedBody.push(makeVulsItem(item, target, user, port, Number(itemIndex)));
    continue;
  }

  // กรณี body ยังไม่ถูก split: target/user หลายบรรทัดอยู่ใน item เดียว
  if (!users.length) {
    throw new Error("Vuls: missing ssh_user");
  }

  if (users.length !== 1 && users.length !== targets.length) {
    throw new Error(
      `Vuls: number of ssh_user must be 1 or equal to number of targets. targets=${targets.length}, users=${users.length}`
    );
  }

  if (ports.length !== 1 && ports.length !== targets.length) {
    throw new Error(
      `Vuls: number of ssh_port must be 1 or equal to number of targets. targets=${targets.length}, ports=${ports.length}`
    );
  }

  targets.forEach((target, index) => {
    const user = users.length === 1 ? users[0] : users[index];
    const port = toPort(ports.length === 1 ? ports[0] : ports[index]);

    normalizedBody.push(makeVulsItem(item, target, user, port, index));
  });
}

const batchTarget = normalizedBody.map(item => item.target).join(",");
const batchUsers = normalizedBody.map(item => item.ssh_user).join(",");
const batchPorts = normalizedBody.map(item => item.ssh_port).join(",");
const firstTarget = normalizedBody[0];

// Keep Vuls multi-host scans as one loop item. Item Lists1 will split body
// once, while Prepare Vuls Payload expands the comma-delimited hosts again.
return [
  {
    json: {
      ...input,
      body: [
        {
          ...firstTarget,
          target: batchTarget,
          target_ip: batchTarget,
          ip: batchTarget,
          ssh_user: batchUsers,
          sshUser: batchUsers,
          username: batchUsers,
          ssh_port: batchPorts,
          sshPort: batchPorts,
          parameters: {
            ...(firstTarget.parameters || {}),
            target_ip: batchTarget,
            ssh_user: batchUsers,
            ssh_port: batchPorts
          }
        }
      ],
      toolName: "vuls",
      target: batchTarget,
      target_ip: batchTarget,
      ssh_user: batchUsers
    }
  }
];

// Normalize structured results from the SSH nodes for AutoPentestX and Guardian.
// This node is connected only to the two pentest tool branches.

function safeText(value, fallback = "", maxLength = 1500) {
  return String(value ?? fallback).slice(0, maxLength);
}

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

function numericCvss(value) {
  if (value === null || value === undefined || value === "") return null;
  const score = Number(value);
  return Number.isFinite(score) && score >= 0 && score <= 10 ? score : null;
}

function normalizeSeverity(value, cvss = null) {
  const severity = String(value || "").toUpperCase();
  const aliases = {
    CRIT: "CRITICAL",
    IMPORTANT: "HIGH",
    MODERATE: "MEDIUM",
    INFORMATIONAL: "INFO",
  };
  const normalized = aliases[severity] || severity;
  if (["CRITICAL", "HIGH", "MEDIUM", "LOW", "INFO"].includes(normalized)) {
    return normalized;
  }

  const score = numericCvss(cvss);
  if (score === null) return "INFO";
  if (score >= 9) return "CRITICAL";
  if (score >= 7) return "HIGH";
  if (score >= 4) return "MEDIUM";
  if (score > 0) return "LOW";
  return "INFO";
}

function buildSummary(findings) {
  return {
    total: findings.length,
    returned: findings.length,
    critical: findings.filter((finding) => finding.severity === "CRITICAL").length,
    high: findings.filter((finding) => finding.severity === "HIGH").length,
    medium: findings.filter((finding) => finding.severity === "MEDIUM").length,
    low: findings.filter((finding) => finding.severity === "LOW").length,
    info: findings.filter((finding) => finding.severity === "INFO").length,
  };
}

function cleanOutput(value) {
  return String(value || "")
    .replace(/\u001B\[[0-?]*[ -/]*[@-~]/g, "")
    .replace(/\r/g, "");
}

function parseStructuredOutput(stdout) {
  const output = cleanOutput(stdout).trim();
  if (!output) {
    throw new Error("Tool returned empty stdout; no JSON result is available.");
  }

  const candidates = [output];
  const lines = output.split("\n").map((line) => line.trim()).filter(Boolean);
  for (let index = lines.length - 1; index >= 0; index -= 1) {
    if (lines[index].startsWith("{") || lines[index].startsWith("[")) {
      candidates.push(lines.slice(index).join("\n"));
    }
  }

  for (const candidate of candidates) {
    try {
      const parsed = JSON.parse(candidate);
      if (parsed && typeof parsed === "object") return parsed;
    } catch (error) {
      // AutoPentestX prints operational messages before its final JSON record.
    }
  }

  throw new Error("Tool stdout did not contain a parseable JSON result.");
}

function makeFinding({
  title,
  severity,
  description,
  remediation,
  target,
  tool,
  cvss = null,
  cves = null,
}) {
  return {
    title: safeText(title, "Unknown Finding", 500),
    severity: normalizeSeverity(severity, cvss),
    description: safeText(description, "No description provided.", 20000),
    remediation: safeText(remediation, "Review the finding and apply appropriate remediation.", 20000),
    target: safeText(target, "N/A", 500),
    cvss: numericCvss(cvss),
    cves: cves && cves.length ? cves : null,
    status: "OPEN",
    tool,
  };
}

function normalizeCve(cve) {
  const cvss = numericCvss(cve.cvss_score ?? cve.cvss ?? cve.score);
  return {
    cveId: safeText(cve.cve_id || cve.cveId || cve.id, "Unknown CVE", 200),
    cvss,
    severity: normalizeSeverity(cve.risk_level || cve.severity, cvss),
    description: safeText(cve.description, "No description provided.", 20000),
  };
}

function normalizeAutoPentest(rawData, target) {
  const findings = [];
  const vulnerabilities = [
    ...asArray(rawData.vulnerabilities),
    ...asArray(rawData.web_vulnerabilities),
    ...asArray(rawData.sql_vulnerabilities),
  ];
  const cves = asArray(rawData.cves_identified);
  const consumedCves = new Set();

  for (const vulnerability of vulnerabilities) {
    const port = String(vulnerability.port ?? "unknown");
    const matchingCves = [];

    cves.forEach((cve, index) => {
      if (String(cve.port ?? "unknown") === port) {
        matchingCves.push(normalizeCve(cve));
        consumedCves.add(index);
      }
    });

    const cvss = numericCvss(vulnerability.cvss ?? vulnerability.cvss_score);
    findings.push(makeFinding({
      title: vulnerability.name || vulnerability.title || "AutoPentestX Vulnerability",
      severity: vulnerability.severity || vulnerability.risk_level,
      description: vulnerability.description,
      remediation: vulnerability.remediation || vulnerability.solution,
      target,
      tool: "autopentestx",
      cvss,
      cves: matchingCves,
    }));
  }

  cves.forEach((cve, index) => {
    if (consumedCves.has(index)) return;
    const normalizedCve = normalizeCve(cve);
    const port = cve.port ?? "unknown";
    const service = cve.service || "service";

    findings.push(makeFinding({
      title: `${String(service).toUpperCase()} CVE on port ${port}: ${normalizedCve.cveId}`,
      severity: normalizedCve.severity,
      description: normalizedCve.description,
      remediation: "Update the affected service and apply vendor security patches.",
      target,
      tool: "autopentestx",
      cvss: normalizedCve.cvss,
      cves: [normalizedCve],
    }));
  });

  return findings;
}

function normalizeGuardian(rawData, target) {
  const findings = [];
  const rawFindings = [
    ...asArray(rawData.findings),
    ...asArray(rawData.vulnerabilities),
  ];

  for (const finding of rawFindings) {
    const cvss = numericCvss(finding.cvss ?? finding.cvss_score ?? finding.riskScore);
    findings.push(makeFinding({
      title: finding.title || finding.name || "Guardian Finding",
      severity: finding.severity || finding.risk_level,
      description: finding.description || finding.detail,
      remediation: finding.remediation || finding.solution,
      target,
      tool: "guardian",
      cvss,
      cves: asArray(finding.cves).map(normalizeCve),
    }));
  }

  const failedExecutions = asArray(rawData.tool_executions).filter((execution) => {
    const exitCode = Number(execution.exit_code ?? execution.code ?? 0);
    const output = cleanOutput(execution.output || execution.stderr || execution.error);
    return exitCode !== 0 || /not installed|could not run|required dependencies|tool execution failed/i.test(output);
  });

  for (const execution of failedExecutions.slice(0, 10)) {
    const tool = safeText(execution.tool || "guardian tool", "guardian tool", 100);
    const output = cleanOutput(execution.output || execution.stderr || execution.error).trim();
    const installHint = output.match(/pip install ['"][^'"]+['"]/i)?.[0]
      || (tool === "httpx" ? "pip install 'httpx[cli]'" : "install the missing CLI tool and verify it is in PATH");

    findings.push(makeFinding({
      title: "Guardian scan incomplete: " + tool + " failed",
      severity: "LOW",
      description: "Guardian could not collect reliable target evidence because " + tool + " failed during execution. Evidence: " + safeText(output, "No tool output was returned.", 1200),
      remediation: "Fix the Guardian runtime before trusting this scan result. Run " + installHint + ", verify " + tool + " is executable in the Guardian venv/PATH, then rerun the scan.",
      target,
      tool: "guardian",
    }));
  }

  if (findings.length) return findings;

  const decisions = asArray(rawData.ai_decisions)
    .map((decision) => safeText(decision.decision || decision.summary, "", 5000))
    .filter(Boolean);
  if (!decisions.length) return [];

  return [makeFinding({
    title: "Guardian AI Security Assessment Report",
    severity: "INFO",
    description: decisions.join("\n\n"),
    remediation: "Review the assessment and validate any recommended actions.",
    target,
    tool: "guardian",
  })];
}

const inputJson = $input.first().json || {};
const loopItem = $("Loop").item.json || {};
const toolName = String(loopItem.toolName || "").toLowerCase().trim();
const target = loopItem.target || loopItem.target_ip || "N/A";
const exitCode = Number(inputJson.exitCode ?? inputJson.code ?? 0);

if (!["autopentestx", "guardian"].includes(toolName)) {
  throw new Error(`Unsupported tool routed into pentest normalizer: ${toolName || "unknown"}.`);
}

if (Number.isFinite(exitCode) && exitCode !== 0) {
  const stderr = cleanOutput(inputJson.stderr).trim();
  const reason = stderr ? ` ${safeText(stderr, "", 500)}` : "";
  throw new Error(`${toolName} SSH execution failed with exit code ${exitCode}.${reason}`);
}

const rawData = parseStructuredOutput(inputJson.stdout);
const findings = toolName === "autopentestx"
  ? normalizeAutoPentest(rawData, target)
  : normalizeGuardian(rawData, target);

return [{
  json: {
    toolName,
    target,
    status: "completed",
    findings,
    summary: buildSummary(findings),
    meta: {
      scanJobId: loopItem.scanJobId || null,
      projectId: loopItem.projectId || null,
    },
  },
}];
